// src/utils/soundUtils.js
import { Audio } from 'expo-av';

// Единый URI для звука клика (используем внешний короткий "бип")
const CLICK_SOUND_URI = 'https://www.soundjay.com/button/beep-07a.wav';

let clickSoundInstance = null; // Переменная для хранения единственного экземпляра звука

export const playClickSound = async () => {
    try {
        if (!clickSoundInstance) {
            // Создаем экземпляр звука только один раз
            const { sound } = await Audio.Sound.createAsync(
                { uri: CLICK_SOUND_URI },
                { shouldPlay: true }
            );
            clickSoundInstance = sound;
            // После завершения воспроизведения устанавливаем позицию в начало
            clickSoundInstance.setOnPlaybackStatusUpdate((status) => {
                if (status.didJustFinish) {
                    clickSoundInstance.setPositionAsync(0);
                }
            });
        } else {
            // Воспроизводим с начала, если экземпляр уже существует
            await clickSoundInstance.replayAsync();
        }

    } catch (error) {
        console.warn('Ошибка воспроизведения звукового эффекта:', error);
        // Не показываем Alert
    }
};

export const unloadClickSound = async () => {
    if (clickSoundInstance) {
        await clickSoundInstance.unloadAsync();
        clickSoundInstance = null;
    }
};
